using Microsoft.Extensions.Options; using MongoDB.Driver; using SmartSolarMicrogrid.Api.Configuration; using SmartSolarMicrogrid.Api.Models;
namespace SmartSolarMicrogrid.Api.Data;
public sealed class MongoContext { public IMongoDatabase Database { get; } public IMongoCollection<User> Users=>Database.GetCollection<User>("Users"); public IMongoCollection<Prosumer> Prosumers=>Database.GetCollection<Prosumer>("Prosumer"); public IMongoCollection<SolarStationInfo> Stations=>Database.GetCollection<SolarStationInfo>("SolarStationInfo"); public IMongoCollection<EnergyBookingSlot> Slots=>Database.GetCollection<EnergyBookingSlot>("EnergyBookingSlots"); public IMongoCollection<EnergyReservation> Reservations=>Database.GetCollection<EnergyReservation>("EnergyReservations"); public MongoContext(IOptions<MongoDbOptions> o) { Database=new MongoClient(o.Value.ConnectionString).GetDatabase(o.Value.DatabaseName); } }
